mapper.select:
select goods.*, category.name as categoryName, supply.supplier_id as supplierId, user.name as supplierName from goods left join category on goods.category_id = category.id left join supply on goods.source_supply_id = supply.id left join user on supply.supplier_id = user.id
and goods.name like concat('%', #{name}, '%') and goods.category_id = #{categoryId}
and supply.supplier_id = #{supplierId}
order by goods.price asc, goods.id desc
order by goods.id desc

mapper.update:
update goods set name = #{name}, img = #{img}, descr = #{descr}, specials = #{specials}, price = #{price},
unit = #{unit}, store = #{store}, category_id = #{categoryId}, source_supply_id = #{sourceSupplyId}
where id = #{id}
